package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsBal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsYear int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsBalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var SchedRecVar SchedRec

var schedFile *os.File
var schedReader *bufio.Reader
var inputDone bool

func main() {
	MainPara()
}

func MainPara() {
	// OPEN INPUT SCHED-FILE
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		inputDone = true
		WsEofFlag = "Y"
	} else {
		schedReader = bufio.NewReader(schedFile)
		WsEofFlag = "N"
		inputDone = false
	}
	ReadPara()
	for !inputDone {
		ProcessPara()
	}
	if schedFile != nil {
		schedFile.Close()
	}
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT PIC 99 zero-padded 2
	countStr := fmt.Sprintf("%02d", WsCount)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func ReadPara() {
	if schedReader == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line, err := schedReader.ReadString('\n')
	if err != nil {
		// EOF handling: if we got data before EOF, still process it
		if len(line) == 0 {
			inputDone = true
			WsEofFlag = "Y"
			return
		}
		// line without newline at EOF, continue to parse it
	} else {
		// strip trailing newline (\n and \r)
		line = strings.TrimRight(line, "\r\n")
	}
	// If line was read with error io.EOF and we have content, the next read will be EOF
	// We need to detect if this was the last line: the next call will hit EOF.
	// For now parse this record.
	// LINE SEQUENTIAL: record length 16, pad with spaces
	rec := []byte(line)
	if len(rec) > 16 {
		rec = rec[:16]
	} else if len(rec) < 16 {
		pad := make([]byte, 16-len(rec))
		for i := range pad {
			pad[i] = ' '
		}
		rec = append(rec, pad...)
	}
	// handle case where ReadString returned EOF and line was empty already handled
	// parse fields
	SchedRecVar.ScAcct = string(rec[0:4])

	// SC-PRIN PIC 9(5)V99 @4 len7
	sPrinRaw := strings.TrimSpace(string(rec[4:11]))
	var prinVal decimal.Decimal
	if sPrinRaw == "" {
		prinVal = decimal.Zero
	} else {
		// digits only
		n, err := strconv.ParseInt(sPrinRaw, 10, 64)
		if err != nil {
			// if contains spaces, try trimmed
			// fallback to 0
			n = 0
		}
		prinVal = decimal.New(n, -2)
	}
	SchedRecVar.ScPrin = prinVal

	// SC-RATE PIC 9(2)V99 @11 len4
	sRateRaw := strings.TrimSpace(string(rec[11:15]))
	var rateVal decimal.Decimal
	if sRateRaw == "" {
		rateVal = decimal.Zero
	} else {
		n, err := strconv.ParseInt(sRateRaw, 10, 64)
		if err != nil {
			n = 0
		}
		rateVal = decimal.New(n, -2)
	}
	SchedRecVar.ScRate = rateVal

	// SC-YEARS PIC 9(1) @15 len1
	sYearsRaw := strings.TrimSpace(string(rec[15:16]))
	var yearsVal int64
	if sYearsRaw == "" {
		yearsVal = 0
	} else {
		n, err := strconv.ParseInt(sYearsRaw, 10, 64)
		if err != nil {
			n = 0
		}
		yearsVal = n
	}
	SchedRecVar.ScYears = yearsVal

	// Check if we had EOF on this read: peek next byte
	if err != nil {
		// This was the last line; next ReadPara will hit EOF.
		// We keep inputDone false for this record, but need to remember that file is exhausted.
		// Implement by not setting inputDone now; the next call will set it.
		// To achieve that, we can set a flag that next read is EOF without consuming.
		// Instead, we can leave schedReader to return EOF next time.
		// No action needed; err was io.EOF but we have a record.
		// Ensure next ReadPara will attempt again and get empty.
		// However our current err handling above already consumed the line.
		// We need to make sure we don't lose the EOF state: next call will get EOF with len 0.
		// That's fine.
	}
}

func ProcessPara() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = storeWsBal(SchedRecVar.ScPrin)

	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > SchedRecVar.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		// SC-RATE /100 -> Shift(-2)
		rateDiv100 := SchedRecVar.ScRate.Shift(-2)
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv100)
		computed := WsBal.Mul(factor)
		// ROUNDED to scale of WS-BAL (2)
		computed = computed.Round(2)
		WsBal = storeWsBal(computed)

		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := fmt.Sprintf("%02d", WsYear)
		fmt.Printf("%s Y%s %s\n", SchedRecVar.ScAcct, yearStr, WsBalEd)

		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecVar.ScAcct, WsBalEd)
	WsCount++
	// ADD 1 TO WS-COUNT handled
	ReadPara()
}

// storeWsBal truncates to scale 2 and keeps low-order digits for PIC 9(8)V99
func storeWsBal(d decimal.Decimal) decimal.Decimal {
	// Truncate to 2 decimals (if already rounded, this is no-op)
	d = d.Truncate(2)
	// Modulus for PIC 9(8)V99: 10^8 = 100000000 for integer part, total cents modulus 10^10
	// Compute cents
	// Use Shift to avoid Div
	centsDec := d.Shift(2).Truncate(0)
	// Convert to int64 if possible; value fits within 10^10 < 2^63
	centsInt := centsDec.IntPart()
	mod := int64(10000000000) // 10^10
	// keep low-order digits: for positive, mod; for negative, preserve sign
	if centsInt >= 0 {
		centsInt = centsInt % mod
	} else {
		// negative: keep low-order digits with sign
		// COBOL stores sign separately; low-order digits of absolute value
		abs := -centsInt % mod
		centsInt = -abs
	}
	// rebuild decimal from cents
	return decimal.New(centsInt, -2)
}

func formatWsBalEd(d decimal.Decimal) string {
	// Ensure truncated to 2 decimals
	d = d.Truncate(2)
	centsDec := d.Shift(2).Truncate(0)
	centsInt := centsDec.IntPart()
	// handle sign
	neg := centsInt < 0
	if neg {
		centsInt = -centsInt
	}
	mod := int64(10000000000)
	centsInt = centsInt % mod // overflow drop handled already, but ensure
	intPart := centsInt / 100
	fracPart := centsInt % 100

	// integer digits 8 chars zero padded
	intStr := fmt.Sprintf("%08d", intPart)
	digits := []byte(intStr) // len 8

	// find first non-zero
	firstNonZero := 8 // beyond
	for i := 0; i < 8; i++ {
		if digits[i] != '0' {
			firstNonZero = i
			break
		}
	}
	// output integer part with commas length 10
	// mapping out[10]
	out := make([]byte, 10)
	// digit indices: 0,1, comma, 2,3,4, comma, 5,6,7
	// helper to decide comma suppression
	// first comma after digit index 1, second after 4
	// suppressed if firstNonZero >1 or >4
	firstCommaSuppressed := firstNonZero > 1
	secondCommaSuppressed := firstNonZero > 4

	// fill
	// out0 = digit0
	// out1 = digit1
	// out2 = comma1
	// out3 = digit2
	// out4 = digit3
	// out5 = digit4
	// out6 = comma2
	// out7 = digit5
	// out8 = digit6
	// out9 = digit7
	digitToOut := []int{0, 1, -1, 2, 3, 4, -1, 5, 6, 7}
	for o := 0; o < 10; o++ {
		di := digitToOut[o]
		if di == -1 {
			// comma position
			if o == 2 {
				if firstCommaSuppressed {
					out[o] = ' '
				} else {
					out[o] = ','
				}
			} else {
				if secondCommaSuppressed {
					out[o] = ' '
				} else {
					out[o] = ','
				}
			}
		} else {
			isZ := di != 7 // only last is 9
			if isZ && di < firstNonZero {
				out[o] = ' '
			} else {
				out[o] = digits[di]
			}
		}
	}
	intPartStr := string(out)
	fracStr := fmt.Sprintf("%02d", fracPart)
	result := intPartStr + "." + fracStr
	if neg {
		// For edited picture without sign, COBOL typically would show sign?
		// Not needed for this program (positive). Handle by prefix '-' replacing leading space if possible.
		// Simple: replace first space with '-'
		b := []byte(result)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				b[i] = '-'
				break
			}
			if b[i] != ',' && b[i] != ' ' {
				// no space left, just prepend minus (overflow)
				// fallback
				break
			}
		}
		// if no space found, just prefix
		hasMinus := false
		for _, c := range b {
			if c == '-' {
				hasMinus = true
				break
			}
		}
		if !hasMinus {
			result = "-" + string(b)
			if len(result) > 13 {
				result = result[len(result)-13:]
			} else {
				// pad?
			}
		} else {
			result = string(b)
		}
	}
	// ensure length 13
	if len(result) < 13 {
		result = strings.Repeat(" ", 13-len(result)) + result
	} else if len(result) > 13 {
		result = result[len(result)-13:]
	}
	return result
}
